
from pathlib import Path
import numpy as np
import pandas as pd
import json

ROOT = Path(
    r"C:\Users\usher\Documents\NDHS-Fl-Research\NDHS_FL_Research"
)

BASELINE = ROOT / "05_preprocessed" / "baseline_test.npz"
EXPANDED = ROOT / "05_preprocessed" / "expanded_test.npz"

METADATA = ROOT / "02_clean_datasets" / "survey_design_metadata.csv"
PARTITIONS = ROOT / "03_partitions" / "fixed_partition_assignments.csv"

print("=" * 70)
print("SW-01: RESPONDENT ID AND SURVEY METADATA LINKAGE")
print("=" * 70)

# These archives are assumed to be locally generated by your own
# research preprocessing pipeline. Only use allow_pickle=True if
# you trust their origin. Never use it on unknown NPZ files.

def load_archive(path):
    with np.load(path, allow_pickle=True) as data:
        return {key: data[key].copy() for key in data.files}

baseline = load_archive(BASELINE)
expanded = load_archive(EXPANDED)

def inspect(name, data):
    print(f"\n--- {name} ---")

    for key, arr in data.items():
        print(
            key,
            "shape:", arr.shape,
            "dtype:", arr.dtype
        )

    ids = data["source_row_id"]
    regions = data["v024"]
    y = data["y"]

    print("Rows:", len(ids))
    print("Unique respondent IDs:", len(pd.unique(ids)))
    print("All IDs unique:", len(pd.unique(ids)) == len(ids))
    print("Missing IDs:", pd.isna(ids).sum())
    print("Missing regions:", pd.isna(regions).sum())
    print("Missing outcomes:", pd.isna(y).sum())
    print("Region values:", pd.Series(regions).value_counts(dropna=False).to_dict())
    print("Outcome values:", pd.Series(y).value_counts(dropna=False).to_dict())

inspect("BASELINE TEST", baseline)
inspect("EXPANDED TEST", expanded)

# Compare respondent ordering
base_ids = baseline["source_row_id"]
expanded_ids = expanded["source_row_id"]

print("\n--- BASELINE / EXPANDED ALIGNMENT ---")
print("Same number of IDs:", len(base_ids) == len(expanded_ids))
print("Same ordered IDs:", np.array_equal(base_ids, expanded_ids))
print("Same outcomes:", np.array_equal(baseline["y"], expanded["y"]))
print("Same regions:", np.array_equal(baseline["v024"], expanded["v024"]))

# Load survey metadata and partition assignments
metadata = pd.read_csv(METADATA, dtype={"source_row_id": "string"})
partitions = pd.read_csv(PARTITIONS, dtype={"source_row_id": "string"})

print("\n--- METADATA STRUCTURE ---")
print(metadata.columns.tolist())
print("Metadata rows:", len(metadata))
print("Metadata duplicate IDs:", metadata["source_row_id"].duplicated().sum())

print("\n--- PARTITION STRUCTURE ---")
print(partitions.columns.tolist())
print("Partition rows:", len(partitions))
print("Partition duplicate IDs:", partitions["source_row_id"].duplicated().sum())
print("Partition values:", partitions["partition"].value_counts(dropna=False).to_dict())

# Convert IDs to strings for cross-file comparison.
# This does not alter the source files.
test_ids = pd.Series(base_ids).astype("string")
metadata_ids = metadata["source_row_id"]
partition_ids = partitions["source_row_id"]

print("\n--- TEST ID LINKAGE ---")
print("Test IDs absent from metadata:", (~test_ids.isin(metadata_ids)).sum())
print("Test IDs absent from partition file:", (~test_ids.isin(partition_ids)).sum())

# Restrict partition records to test respondents.
test_partition = partitions[
    partitions["source_row_id"].isin(test_ids)
].copy()

print("Matched partition rows:", len(test_partition))
print(
    "Matched partition labels:",
    test_partition["partition"].value_counts(dropna=False).to_dict()
)

# Check region/outcome agreement where IDs match.
test_frame = pd.DataFrame({
    "source_row_id": test_ids,
    "archive_region": pd.Series(baseline["v024"]).astype("string"),
    "archive_outcome": pd.Series(baseline["y"])
})

joined = test_frame.merge(
    partitions[["source_row_id", "v024", "facility_delivery", "partition"]],
    on="source_row_id",
    how="left",
    validate="one_to_one"
)

print("\n--- REGION / OUTCOME CONCORDANCE ---")
print("Missing partition region:", joined["v024"].isna().sum())
print("Missing partition outcome:", joined["facility_delivery"].isna().sum())

print(
    "Region mismatches:",
    (joined["archive_region"] != joined["v024"].astype("string")).sum()
)

print(
    "Outcome mismatches:",
    (joined["archive_outcome"] != joined["facility_delivery"]).sum()
)

# Survey metadata linkage
metadata_join = test_frame.merge(
    metadata,
    on="source_row_id",
    how="left",
    validate="one_to_one"
)

print("\n--- SURVEY DESIGN FIELD AVAILABILITY ---")
for field in ["v005", "survey_weight", "v021", "v022", "v023", "v001", "v024"]:
    if field in metadata_join.columns:
        print(
            field,
            "missing:", metadata_join[field].isna().sum(),
            "unique:", metadata_join[field].nunique(dropna=True)
        )
    else:
        print(field, "NOT PRESENT")

# Inspect nested configuration in one manifest.
output_dir = (
    ROOT / "09_flower_implementation_v1_2_1"
    / "outputs" / "confirmatory_v2_seeds_42_51"
)

manifest_paths = sorted(output_dir.rglob("run_manifest.json"))

print("\n--- FIRST MANIFEST CONFIGURATION ---")
if manifest_paths:
    with open(manifest_paths[0], encoding="utf-8") as f:
        manifest = json.load(f)

    print(json.dumps(manifest.get("configuration", {}), indent=2))

print("\n" + "=" * 70)
print("CHECK COMPLETE — NO SOURCE FILES MODIFIED")
print("=" * 70)
